/* ═══════════════════════════════════════════════════════════════════
   DARE DECK — visual system
   ═══════════════════════════════════════════════════════════════════ */

:root {
  --bg: #09060f;
  --bg-soft: #120b1c;
  --panel: rgba(21, 13, 33, 0.78);
  --panel-solid: #150d21;
  --paper: #f7f4ff;
  --muted: #a99fbc;
  --muted-2: #7e7392;
  --line: rgba(255, 255, 255, 0.11);
  --line-strong: rgba(255, 255, 255, 0.2);
  --acid: #f6ff5c;
  --acid-deep: #d8e600;
  --pink: #ff5ca8;
  --cyan: #67e8f9;
  --green: #4ade80;
  --red: #fb7185;
  --orange: #fb923c;
  --shadow-lg: 0 30px 80px rgba(0, 0, 0, 0.5);
  --font-display: "Arial Black", "Arial Bold", Impact, "Trebuchet MS", system-ui, sans-serif;
  --font-body: "Avenir Next", "Segoe UI", "Trebuchet MS", system-ui, -apple-system, sans-serif;
  --radius: 28px;
  --ease: cubic-bezier(0.2, 0.8, 0.2, 1);
}

*, *::before, *::after { box-sizing: border-box; }

html {
  min-height: 100%;
  background: var(--bg);
  -webkit-text-size-adjust: 100%;
}

body {
  min-height: 100%;
  min-height: 100dvh;
  margin: 0;
  overflow-x: hidden;
  background:
    radial-gradient(ellipse 80% 55% at 12% 8%, rgba(255, 92, 168, 0.13), transparent 60%),
    radial-gradient(ellipse 70% 60% at 88% 18%, rgba(103, 232, 249, 0.1), transparent 60%),
    radial-gradient(ellipse 90% 70% at 50% 105%, rgba(246, 255, 92, 0.08), transparent 62%),
    var(--bg);
  color: var(--paper);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body.in-game { overscroll-behavior: none; }

button, input { font: inherit; }
button { color: inherit; }
button:focus-visible, input:focus-visible, a:focus-visible {
  outline: 3px solid var(--acid);
  outline-offset: 3px;
}
[hidden] { display: none !important; }

#fx {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 80;
  pointer-events: none;
}

.backdrop {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(2px);
  opacity: 0.7;
  animation: drift 18s ease-in-out infinite alternate;
}
.orb-a {
  width: 42vw;
  height: 42vw;
  min-width: 380px;
  min-height: 380px;
  top: -18vw;
  left: -10vw;
  background: radial-gradient(circle, rgba(255, 92, 168, 0.18), transparent 68%);
}
.orb-b {
  width: 46vw;
  height: 46vw;
  min-width: 380px;
  min-height: 380px;
  right: -16vw;
  top: 10vh;
  background: radial-gradient(circle, rgba(103, 232, 249, 0.15), transparent 68%);
  animation-delay: -7s;
}
.orb-c {
  width: 54vw;
  height: 40vw;
  min-width: 420px;
  min-height: 320px;
  left: 26%;
  bottom: -22vw;
  background: radial-gradient(circle, rgba(246, 255, 92, 0.1), transparent 68%);
  animation-delay: -13s;
}

.grain {
  position: absolute;
  inset: 0;
  opacity: 0.035;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}

/* ── Screens ────────────────────────────────────────────────────────── */
.screen {
  position: relative;
  z-index: 1;
  display: none;
  min-height: 100dvh;
}
.screen.is-active {
  display: flex;
  flex-direction: column;
  animation: screenIn 0.45s var(--ease) both;
}

/* ── Header ─────────────────────────────────────────────────────────── */
.site-header {
  position: relative;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  width: min(1240px, 100%);
  margin: 0 auto;
  padding: max(20px, env(safe-area-inset-top)) clamp(18px, 4vw, 40px) 0;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  color: var(--paper);
  text-decoration: none;
  line-height: 1;
}
.brand-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: var(--acid);
  color: #0a0710;
  font-family: var(--font-display);
  font-size: 25px;
  font-weight: 900;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.2), 0 8px 24px rgba(246, 255, 92, 0.25);
  transform: rotate(-4deg);
}
.brand-type {
  font-family: var(--font-display);
  font-size: 19px;
  font-weight: 900;
  letter-spacing: -0.02em;
}
.brand-type span { color: var(--acid); margin-left: 2px; }

.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}
.header-chip {
  padding: 7px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
}
.icon-button {
  display: inline-grid;
  place-items: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--paper);
  font-size: 17px;
  cursor: pointer;
  transition: background 0.18s, border-color 0.18s, transform 0.18s;
}
.icon-button:hover { background: rgba(255, 255, 255, 0.09); border-color: var(--line-strong); }
.icon-button:active { transform: scale(0.95); }
.text-button {
  padding: 10px 14px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--muted);
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition: color 0.18s, background 0.18s;
}
.text-button:hover { color: var(--paper); background: rgba(255, 255, 255, 0.06); }
.sound-off { display: none; }
body.is-muted .sound-on { display: none; }
body.is-muted .sound-off { display: inline; }

/* ── Home layout ────────────────────────────────────────────────────── */
.home-main {
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(360px, 0.92fr);
  align-items: center;
  gap: clamp(32px, 5vw, 76px);
  width: min(1240px, 100%);
  margin: auto;
  padding: clamp(34px, 6vh, 74px) clamp(18px, 4vw, 40px);
}

.hero { min-width: 0; }
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin: 0 0 18px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--acid);
  box-shadow: 0 0 0 4px rgba(246, 255, 92, 0.12);
  animation: blink 2.4s ease-in-out infinite;
}

h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(3.1rem, 7.2vw, 6.6rem);
  font-weight: 900;
  line-height: 0.83;
  letter-spacing: -0.055em;
  text-transform: uppercase;
}
h1 span {
  color: var(--acid);
  text-shadow: 0 0 40px rgba(246, 255, 92, 0.18);
}

.hero-copy {
  max-width: 530px;
  margin: 24px 0 0;
  color: var(--muted);
  font-size: clamp(15px, 1.3vw, 17px);
  line-height: 1.65;
}

.hero-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 24px;
}
.badge {
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.035);
  color: #d9d2e6;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.015em;
}

.safety-note {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  max-width: 520px;
  margin: 26px 0 0;
  color: var(--muted-2);
  font-size: 12px;
  line-height: 1.55;
}

/* ── Deck fan ───────────────────────────────────────────────────────── */
.deck-fan {
  position: relative;
  width: min(400px, 92%);
  height: 210px;
  margin: 42px 0 0 4px;
}
.fan-card {
  position: absolute;
  left: 12px;
  bottom: 0;
  width: 250px;
  height: 158px;
  padding: 18px;
  border: 1px solid var(--line-strong);
  border-radius: 20px;
  background: linear-gradient(155deg, #241633, #150d21);
  box-shadow: 0 18px 36px rgba(0, 0, 0, 0.35);
  transform-origin: 50% 120%;
  transition: transform 0.35s var(--ease);
}
.fan-card span { font-size: 27px; }
.fan-card small {
  position: absolute;
  right: 16px;
  bottom: 14px;
  color: var(--muted-2);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.18em;
}
.fan-0 { transform: rotate(-12deg) translate(-13px, 8px); }
.fan-1 { transform: rotate(-5deg) translate(-3px, 2px); }
.fan-2 { transform: rotate(3deg) translate(12px, 0); }
.deck-fan:hover .fan-0 { transform: rotate(-16deg) translate(-22px, 7px); }
.deck-fan:hover .fan-1 { transform: rotate(-7deg) translate(-7px, 2px); }
.deck-fan:hover .fan-2 { transform: rotate(5deg) translate(18px, 0); }
.fan-front {
  width: 276px;
  height: 172px;
  bottom: 12px;
  left: 42px;
  padding: 16px 18px;
  background: linear-gradient(160deg, #fffde1, #f6ff5c 55%, #d9e700);
  color: #100b18;
  border-color: rgba(255, 255, 255, 0.5);
  transform: rotate(-2deg) translateY(-4px);
  box-shadow: 0 24px 54px rgba(0, 0, 0, 0.5), 0 0 50px rgba(246, 255, 92, 0.1);
  display: flex;
  flex-direction: column;
}
.fan-front-top, .fan-front-foot {
  display: flex;
  justify-content: space-between;
  color: rgba(16, 11, 24, 0.68);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.16em;
}
.fan-front strong {
  margin: auto 0;
  font-family: var(--font-display);
  font-size: 21px;
  font-weight: 900;
  line-height: 1.02;
  letter-spacing: -0.035em;
  text-transform: uppercase;
}

/* ── Setup panel ────────────────────────────────────────────────────── */
.setup {
  position: relative;
  padding: clamp(20px, 2.6vw, 30px);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.035), transparent 38%),
    var(--panel);
  box-shadow: var(--shadow-lg), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}
.setup::before {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(140deg, rgba(246, 255, 92, 0.35), transparent 30%, transparent 70%, rgba(255, 92, 168, 0.22));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}
.setup-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
}
.setup-kicker,
.modal-kicker,
.end-kicker {
  margin: 0 0 5px;
  color: var(--acid);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.2em;
}
.setup h2, .modal h2, .end-card h2 {
  margin: 0;
  font-family: var(--font-display);
  font-weight: 900;
  letter-spacing: -0.04em;
  line-height: 1;
}
.setup h2 { font-size: 31px; }
.deck-pill {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: rgba(0, 0, 0, 0.18);
  line-height: 1.05;
}
.deck-pill strong { color: var(--acid); font-size: 20px; }
.deck-pill span { margin-top: 3px; color: var(--muted-2); font-size: 9px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; }

.segmented {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: rgba(0, 0, 0, 0.22);
}
.mode-switch { margin-bottom: 6px; }
.seg-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 42px;
  padding: 8px 10px;
  border: 0;
  border-radius: 11px;
  background: transparent;
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  transition: background 0.18s, color 0.18s, transform 0.18s;
}
.seg-btn:hover { color: var(--paper); background: rgba(255, 255, 255, 0.06); }
.seg-btn.is-active {
  background: var(--paper);
  color: #100b18;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
}
.seg-btn.is-active:hover { background: var(--paper); }

.option-block { margin-top: 18px; }
.label-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 9px;
}
.label-row.turns-label { margin-top: 16px; }
.label { color: var(--paper); font-size: 12px; font-weight: 800; letter-spacing: 0.04em; text-transform: uppercase; }
.label-hint { color: var(--muted-2); font-size: 11px; font-weight: 600; }
.mini-link {
  padding: 2px;
  border: 0;
  background: transparent;
  color: var(--acid);
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}
.mini-link:hover { text-decoration: underline; }
.pill-row { display: flex; flex-wrap: wrap; gap: 7px; }
.pill {
  min-width: 48px;
  min-height: 39px;
  padding: 7px 13px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.03);
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.18s var(--ease);
}
.pill:hover { border-color: var(--line-strong); color: var(--paper); }
.pill.is-active {
  border-color: var(--acid);
  background: rgba(246, 255, 92, 0.12);
  color: var(--acid);
  box-shadow: inset 0 0 0 1px rgba(246, 255, 92, 0.25);
}
.intensity-switch .seg-btn.is-active {
  background: var(--pink);
  color: #fff;
}
.intensity-switch .seg-btn[data-level="1"].is-active { background: var(--cyan); color: #071116; }
.intensity-switch .seg-btn[data-level="3"].is-active { background: var(--acid); color: #100b18; }

/* Players */
.player-list { display: flex; flex-direction: column; gap: 6px; }
.player-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 5px 5px 7px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.025);
}
.player-dot {
  flex: 0 0 24px;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 8px;
  background: var(--dot, var(--pink));
  color: #100b18;
  font-size: 10px;
  font-weight: 900;
}
.player-input {
  min-width: 0;
  flex: 1;
  padding: 5px 2px;
  border: 0;
  background: transparent;
  color: var(--paper);
  font-size: 14px;
  font-weight: 700;
}
.player-input:focus { outline: none; }
.player-input::placeholder { color: var(--muted-2); }
.remove-player {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--muted-2);
  font-size: 15px;
  cursor: pointer;
}
.remove-player:hover { background: rgba(251, 113, 133, 0.12); color: var(--red); }
.remove-player:disabled { opacity: 0.25; cursor: not-allowed; }
.add-player-row { display: flex; gap: 7px; margin-top: 7px; }
.add-player-row input {
  min-width: 0;
  flex: 1;
  height: 39px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: rgba(0, 0, 0, 0.2);
  color: var(--paper);
  font-size: 13px;
}
.add-player-row input::placeholder { color: var(--muted-2); }
.small-button {
  height: 39px;
  padding: 0 15px;
  border: 1px solid var(--line-strong);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.07);
  color: var(--paper);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}
.small-button:hover { background: rgba(255, 255, 255, 0.12); }

/* Category chips */
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 32px;
  padding: 5px 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.025);
  color: var(--muted-2);
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  opacity: 0.7;
  transition: all 0.16s var(--ease);
}
.chip:hover { opacity: 1; border-color: var(--line-strong); }
.chip.is-on {
  border-color: var(--cat);
  background: rgba(255, 255, 255, 0.055);
  color: var(--paper);
  opacity: 1;
  box-shadow: inset 0 0 0 1px var(--cat);
}
.chip .chip-icon { font-size: 13px; }

.props-note {
  display: flex;
  gap: 9px;
  align-items: flex-start;
  margin-top: 18px;
  padding: 10px 12px;
  border: 1px dashed var(--line-strong);
  border-radius: 12px;
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.45;
}
.props-note > span:first-child { flex: 0 0 auto; }

.primary-button, .secondary-button, .danger-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 52px;
  padding: 0 22px;
  border-radius: 15px;
  border: 1px solid transparent;
  font-size: 14px;
  font-weight: 900;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition: transform 0.16s var(--ease), box-shadow 0.16s, background 0.16s, border-color 0.16s;
}
.primary-button {
  background: var(--acid);
  color: #100b18;
  box-shadow: 0 10px 28px rgba(246, 255, 92, 0.18), inset 0 1px 0 rgba(255, 255, 255, 0.55);
}
.primary-button:hover { transform: translateY(-2px); box-shadow: 0 16px 38px rgba(246, 255, 92, 0.26); }
.primary-button:active { transform: translateY(0) scale(0.99); }
.big-button { width: 100%; min-height: 58px; margin-top: 18px; font-size: 16px; position: relative; }
.big-button::after {
  content: "→";
  position: absolute;
  right: 20px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 20px;
}
.secondary-button {
  border-color: var(--line-strong);
  background: rgba(255, 255, 255, 0.055);
  color: var(--paper);
}
.secondary-button:hover { background: rgba(255, 255, 255, 0.1); transform: translateY(-1px); }
.danger-button {
  background: rgba(251, 113, 133, 0.15);
  border-color: rgba(251, 113, 133, 0.5);
  color: #ffb3bf;
}
.danger-button:hover { background: rgba(251, 113, 133, 0.24); }
.setup-foot {
  margin: 12px 0 0;
  color: var(--muted-2);
  font-size: 10.5px;
  text-align: center;
  letter-spacing: 0.02em;
}
.setup-foot strong { color: var(--muted); }

.site-footer {
  display: flex;
  justify-content: center;
  gap: 10px;
  width: min(1240px, 100%);
  margin: 0 auto;
  padding: 0 24px max(22px, env(safe-area-inset-bottom));
  color: var(--muted-2);
  font-size: 11px;
  letter-spacing: 0.04em;
}
.footer-dot { color: var(--acid); }

/* ── Game screen ────────────────────────────────────────────────────── */
.game-screen {
  padding: max(14px, env(safe-area-inset-top)) clamp(13px, 3vw, 28px) max(14px, env(safe-area-inset-bottom));
}
.game-screen.is-active { display: flex; flex-direction: column; }

.game-header {
  display: flex;
  align-items: center;
  gap: 12px;
  width: min(760px, 100%);
  margin: 0 auto;
  padding: 2px 0 13px;
}
.game-header .icon-button { width: 42px; height: 42px; flex: 0 0 auto; }
.progress-wrap { flex: 1; min-width: 0; }
.progress-labels {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 7px;
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.progress-labels span:last-child { color: var(--muted-2); }
.progress-track {
  height: 6px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.08);
}
.progress-fill {
  width: 0;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--pink), var(--acid));
  transition: width 0.45s var(--ease);
  box-shadow: 0 0 12px rgba(246, 255, 92, 0.35);
}
.score-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  flex: 0 0 auto;
  min-width: 65px;
  height: 42px;
  padding: 0 11px;
  border: 1px solid rgba(246, 255, 92, 0.3);
  border-radius: 13px;
  background: rgba(246, 255, 92, 0.09);
  color: var(--acid);
  font-size: 15px;
}
.score-pill strong { font-size: 16px; font-weight: 900; }
.score-pill.is-popping { animation: scorePop 0.45s var(--ease); }

.players-strip {
  display: flex;
  gap: 7px;
  width: min(760px, 100%);
  margin: 0 auto;
  padding: 0 0 11px;
  overflow-x: auto;
  scrollbar-width: none;
}
.players-strip::-webkit-scrollbar { display: none; }
.player-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  flex: 0 0 auto;
  padding: 6px 10px 6px 6px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.03);
  color: var(--muted);
  font-size: 11.5px;
  font-weight: 700;
  transition: all 0.25s var(--ease);
}
.player-chip .player-dot { width: 25px; height: 25px; font-size: 9px; }
.player-chip .chip-score { color: var(--muted-2); font-size: 10px; font-weight: 900; }
.player-chip.is-active {
  border-color: var(--acid);
  background: rgba(246, 255, 92, 0.1);
  color: var(--paper);
  box-shadow: 0 0 0 1px rgba(246, 255, 92, 0.18);
}
.player-chip.is-active .chip-score { color: var(--acid); }

.game-main {
  display: flex;
  flex-direction: column;
  justify-content: center;
  width: min(652px, 100%);
  margin: 0 auto;
  flex: 1;
}
.turn-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 0 3px 11px;
}
.turn-who { display: flex; align-items: center; gap: 10px; min-width: 0; }
.turn-avatar {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.05);
  font-size: 18px;
}
.turn-kicker {
  margin: 0 0 1px;
  color: var(--muted-2);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.18em;
}
.turn-name {
  margin: 0;
  max-width: 52vw;
  overflow: hidden;
  color: var(--paper);
  font-size: 16px;
  font-weight: 900;
  letter-spacing: -0.02em;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.timer-status {
  flex: 0 0 auto;
  padding: 6px 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.timer-status.is-live { border-color: rgba(74, 222, 128, 0.4); color: var(--green); background: rgba(74, 222, 128, 0.08); }
.timer-status.is-paused { border-color: rgba(251, 191, 36, 0.4); color: #fbbf24; }
.timer-status.is-done { border-color: rgba(251, 113, 133, 0.4); color: var(--red); }

/* Card */
.card-stage {
  position: relative;
  width: min(600px, 100%);
  margin: 0 auto;
  perspective: 1300px;
}
.card-shadow {
  position: absolute;
  inset: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #1a1028;
  pointer-events: none;
}
.card-shadow-a { transform: rotate(-3.2deg) translate(-7px, 8px); opacity: 0.55; }
.card-shadow-b { transform: rotate(2.4deg) translate(7px, 5px); opacity: 0.35; }

.game-card {
  --cat: var(--cyan);
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  min-height: clamp(345px, 49vh, 452px);
  padding: clamp(21px, 3.4vw, 34px);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: var(--radius);
  background:
    radial-gradient(ellipse 90% 80% at 110% -20%, color-mix(in srgb, var(--cat) 24%, transparent), transparent 58%),
    radial-gradient(ellipse 70% 70% at -10% 110%, color-mix(in srgb, var(--cat) 10%, transparent), transparent 55%),
    linear-gradient(155deg, #1d122b, #100a1a 72%);
  box-shadow: 0 34px 70px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.12);
  transform-style: preserve-3d;
  transition: border-color 0.3s;
}
.game-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background:
    linear-gradient(115deg, transparent 32%, rgba(255, 255, 255, 0.055) 46%, transparent 60%);
  pointer-events: none;
}
.game-card.is-dealing { animation: dealIn 0.52s var(--ease) both; }
.game-card.is-success { border-color: rgba(74, 222, 128, 0.55); }
.game-card.is-fail { border-color: rgba(251, 113, 133, 0.5); }

.card-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.category-badge, .level-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 11px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  white-space: nowrap;
}
.category-badge {
  border: 1px solid color-mix(in srgb, var(--cat) 55%, transparent);
  background: color-mix(in srgb, var(--cat) 14%, transparent);
  color: var(--cat);
}
.level-badge {
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.04);
  color: var(--muted);
}
.level-badge::before { content: "◆"; color: var(--cat); font-size: 7px; }

.card-icon {
  display: grid;
  place-items: center;
  width: clamp(48px, 7.5vw, 66px);
  height: clamp(48px, 7.5vw, 66px);
  margin-top: clamp(18px, 3.5vh, 32px);
  border: 1px solid color-mix(in srgb, var(--cat) 38%, transparent);
  border-radius: 20px;
  background: color-mix(in srgb, var(--cat) 12%, transparent);
  font-size: clamp(25px, 4.2vw, 35px);
  box-shadow: 0 10px 30px color-mix(in srgb, var(--cat) 12%, transparent);
}
.card-text {
  margin: clamp(14px, 2.6vh, 22px) 0 0;
  color: var(--paper);
  font-family: var(--font-display);
  font-size: clamp(1.42rem, 3.2vw, 2.05rem);
  font-weight: 900;
  line-height: 1.13;
  letter-spacing: -0.035em;
  text-wrap: balance;
}
.card-foot {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
  margin-top: auto;
  padding-top: clamp(18px, 3vh, 28px);
  border-top: 1px dashed rgba(255, 255, 255, 0.12);
}
.timer-cluster { flex: 0 0 auto; }
.timer-ring-wrap {
  position: relative;
  display: grid;
  place-items: center;
  width: clamp(58px, 8vw, 70px);
  height: clamp(58px, 8vw, 70px);
}
.timer-ring { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); }
.timer-track, .timer-progress {
  fill: none;
  stroke-width: 5;
}
.timer-track { stroke: rgba(255, 255, 255, 0.09); }
.timer-progress {
  stroke: var(--cat);
  stroke-dasharray: 169.65;
  stroke-dashoffset: 0;
  stroke-linecap: round;
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--cat) 55%, transparent));
  transition: stroke-dashoffset 0.1s linear;
}
.timer-ring-wrap.is-off .timer-progress { opacity: 0.18; }
.timer-ring-wrap.is-off .timer-text { color: var(--muted-2); font-size: 15px; }
.timer-text {
  position: relative;
  z-index: 1;
  color: var(--paper);
  font-size: clamp(13px, 1.8vw, 15px);
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}
.timer-ring-wrap.is-urgent .timer-progress { stroke: var(--red); animation: urgent 0.7s ease-in-out infinite; }
.timer-ring-wrap.is-urgent .timer-text { color: var(--red); }
.card-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;
  min-width: 0;
  text-align: right;
}
.card-hint { color: var(--muted); font-size: 11px; line-height: 1.35; }
.card-index { color: var(--muted-2); font-size: 9px; font-weight: 900; letter-spacing: 0.14em; }

.result-stamp {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 24px;
  border-radius: inherit;
  background: rgba(9, 6, 15, 0.74);
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
  text-align: center;
  animation: stampIn 0.34s var(--ease) both;
}
.result-stamp strong {
  font-family: var(--font-display);
  font-size: clamp(2.3rem, 7vw, 4.2rem);
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -0.05em;
  text-transform: uppercase;
  color: var(--green);
  text-shadow: 0 0 30px rgba(74, 222, 128, 0.35);
}
.result-stamp span {
  padding: 6px 12px;
  border: 1px solid currentColor;
  border-radius: 999px;
  color: var(--green);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.result-stamp.is-fail strong, .result-stamp.is-fail span { color: var(--red); }
.result-stamp.is-skip strong, .result-stamp.is-skip span { color: var(--muted); }
.result-stamp small { max-width: 340px; color: var(--muted); font-size: 12px; line-height: 1.4; }

/* Controls */
.controls {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  width: min(600px, 100%);
  margin: 15px auto 0;
}
.controls .primary-button,
.controls .secondary-button,
.controls .danger-button,
.controls .ghost-button {
  flex: 1 1 0;
  min-width: 120px;
  min-height: 50px;
  padding: 0 13px;
  font-size: 13px;
}
.controls .wide { flex: 1 1 100%; }
.ghost-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 14px;
  border: 1px solid transparent;
  border-radius: 13px;
  background: transparent;
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: color 0.16s, background 0.16s;
}
.ghost-button:hover { color: var(--paper); background: rgba(255, 255, 255, 0.05); }
.controls .skip-button { flex: 0 0 auto; min-width: 100%; }
.keyboard-hint {
  margin: 11px 0 0;
  color: var(--muted-2);
  font-size: 9.5px;
  letter-spacing: 0.04em;
  text-align: center;
}

/* ── End screen ─────────────────────────────────────────────────────── */
.end-screen { justify-content: center; }
.end-wrap {
  display: grid;
  place-items: center;
  width: 100%;
  padding: clamp(24px, 6vh, 70px) clamp(16px, 4vw, 30px) max(30px, env(safe-area-inset-bottom));
}
.end-card {
  width: min(720px, 100%);
  padding: clamp(26px, 4.5vw, 48px);
  border: 1px solid var(--line);
  border-radius: 34px;
  background:
    radial-gradient(ellipse 90% 80% at 50% -20%, rgba(246, 255, 92, 0.13), transparent 55%),
    var(--panel);
  box-shadow: var(--shadow-lg), inset 0 1px 0 rgba(255, 255, 255, 0.09);
  backdrop-filter: blur(18px);
  text-align: center;
  animation: screenIn 0.5s var(--ease) both;
}
.end-icon {
  display: grid;
  place-items: center;
  width: 78px;
  height: 78px;
  margin: 0 auto 18px;
  border: 1px solid rgba(246, 255, 92, 0.3);
  border-radius: 24px;
  background: rgba(246, 255, 92, 0.09);
  font-size: 38px;
  box-shadow: 0 0 40px rgba(246, 255, 92, 0.1);
  transform: rotate(-3deg);
}
.end-kicker { color: var(--muted-2); }
.end-card h2 {
  margin-top: 8px;
  font-size: clamp(2.4rem, 6vw, 4.2rem);
  line-height: 0.92;
  text-transform: uppercase;
}
.end-subtitle {
  max-width: 480px;
  margin: 14px auto 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.55;
}
.end-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-top: 26px;
}
.stat {
  padding: 13px 8px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: rgba(0, 0, 0, 0.17);
}
.stat strong { display: block; color: var(--paper); font-size: clamp(20px, 3vw, 27px); font-weight: 900; letter-spacing: -0.03em; }
.stat span { color: var(--muted-2); font-size: 9px; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; }
.podium { display: flex; flex-direction: column; gap: 7px; margin-top: 20px; text-align: left; }
.podium-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.03);
}
.podium-row.is-winner { border-color: rgba(246, 255, 92, 0.4); background: rgba(246, 255, 92, 0.07); }
.podium-rank { width: 24px; color: var(--muted-2); font-size: 15px; font-weight: 900; text-align: center; }
.podium-row.is-winner .podium-rank { color: var(--acid); }
.podium-name { flex: 1; min-width: 0; overflow: hidden; color: var(--paper); font-size: 13px; font-weight: 800; text-overflow: ellipsis; white-space: nowrap; }
.podium-score { color: var(--muted); font-size: 11px; font-weight: 900; }
.podium-row.is-winner .podium-score { color: var(--acid); }
.end-favorite { margin-top: 16px; color: var(--muted); font-size: 11.5px; }
.end-favorite strong { color: var(--paper); }
.end-actions { display: flex; gap: 8px; margin-top: 26px; }
.end-actions .primary-button, .end-actions .secondary-button { flex: 1; }
.lifetime { margin: 15px 0 0; color: var(--muted-2); font-size: 10px; letter-spacing: 0.04em; }

/* ── Modal ──────────────────────────────────────────────────────────── */
.modal {
  width: min(720px, calc(100vw - 28px));
  max-height: min(88dvh, 760px);
  margin: auto;
  padding: 0;
  overflow: auto;
  border: 1px solid var(--line-strong);
  border-radius: 28px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.045), transparent 30%),
    #140d20;
  color: var(--paper);
  box-shadow: 0 40px 100px rgba(0, 0, 0, 0.65);
}
.modal::backdrop {
  background: rgba(5, 3, 9, 0.76);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.modal[open] { animation: modalIn 0.28s var(--ease) both; }
.modal form { padding: clamp(22px, 4vw, 34px); }
.modal-small { width: min(470px, calc(100vw - 28px)); }
.modal-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 18px; }
.modal h2 { font-size: clamp(28px, 4vw, 40px); }
.modal-close { flex: 0 0 auto; width: 40px; height: 40px; }
.rules-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.rule {
  display: flex;
  gap: 11px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: rgba(255, 255, 255, 0.025);
  text-align: left;
}
.rule-num {
  flex: 0 0 27px;
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  border-radius: 9px;
  background: rgba(246, 255, 92, 0.1);
  color: var(--acid);
  font-size: 10px;
  font-weight: 900;
}
.rule strong { display: block; margin-bottom: 3px; font-size: 12.5px; }
.rule p { margin: 0; color: var(--muted); font-size: 11.5px; line-height: 1.45; }
.rule-warn { border-color: rgba(251, 113, 133, 0.28); }
.rule-warn .rule-num { background: rgba(251, 113, 133, 0.12); color: var(--red); }
.modal-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
}
.modal-foot p { margin: 0; color: var(--muted-2); font-size: 11px; }
.modal-copy { margin: 12px 0 0; color: var(--muted); font-size: 13px; line-height: 1.55; }
.modal-actions { display: flex; gap: 8px; margin-top: 22px; }
.modal-actions > * { flex: 1; }

/* ── Toast ──────────────────────────────────────────────────────────── */
.toast {
  position: fixed;
  left: 50%;
  top: max(18px, env(safe-area-inset-top));
  z-index: 110;
  max-width: min(460px, calc(100vw - 28px));
  padding: 11px 16px;
  border: 1px solid var(--line-strong);
  border-radius: 13px;
  background: rgba(20, 13, 32, 0.95);
  color: var(--paper);
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
  font-size: 12px;
  font-weight: 700;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, -12px);
  transition: opacity 0.22s, transform 0.22s var(--ease);
}
.toast.is-visible { opacity: 1; transform: translate(-50%, 0); }

/* ── Motion ─────────────────────────────────────────────────────────── */
@keyframes screenIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes dealIn {
  0% { opacity: 0.2; transform: rotateY(72deg) translateY(14px) scale(0.96); }
  70% { opacity: 1; transform: rotateY(-4deg) translateY(0) scale(1.003); }
  100% { opacity: 1; transform: rotateY(0) translateY(0) scale(1); }
}
@keyframes stampIn {
  from { opacity: 0; transform: scale(0.94); }
  to { opacity: 1; transform: scale(1); }
}
@keyframes scorePop {
  0% { transform: scale(1); }
  45% { transform: scale(1.16); }
  100% { transform: scale(1); }
}
@keyframes modalIn {
  from { opacity: 0; transform: translateY(12px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes drift {
  from { transform: translate3d(-2%, -2%, 0) scale(1); }
  to { transform: translate3d(3%, 3%, 0) scale(1.06); }
}
@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}
@keyframes urgent {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

/* ── Responsive ─────────────────────────────────────────────────────── */
@media (max-width: 940px) {
  .home-main {
    grid-template-columns: 1fr;
    gap: 30px;
    align-items: start;
    max-width: 660px;
    padding-top: 30px;
  }
  .hero { text-align: left; }
  .deck-fan { display: none; }
  .safety-note { margin-top: 18px; }
  .setup { width: 100%; }
}

@media (max-width: 620px) {
  .site-header { padding-left: 16px; padding-right: 16px; }
  .header-chip { display: none; }
  .text-button { padding: 10px 10px; font-size: 12.5px; }
  .home-main { padding: 24px 16px 18px; }
  h1 { font-size: clamp(2.9rem, 15vw, 4.6rem); }
  .hero-copy { margin-top: 18px; font-size: 14.5px; }
  .hero-badges { margin-top: 18px; }
  .badge { font-size: 10.5px; padding: 7px 10px; }
  .setup { border-radius: 24px; padding: 19px; }
  .setup h2 { font-size: 26px; }
  .seg-btn { font-size: 12px; }
  .game-screen { padding-left: 10px; padding-right: 10px; }
  .game-main { width: 100%; }
  .turn-name { font-size: 15px; }
  .game-card { min-height: clamp(330px, 50vh, 420px); border-radius: 24px; }
  .card-shadow { border-radius: 24px; }
  .card-text { font-size: clamp(1.3rem, 5.7vw, 1.65rem); }
  .card-meta { max-width: 160px; }
  .card-hint { font-size: 10px; }
  .controls { gap: 7px; }
  .controls .primary-button, .controls .secondary-button, .controls .danger-button { min-height: 48px; font-size: 12.5px; }
  .end-stats { grid-template-columns: 1fr 1fr; }
  .rules-grid { grid-template-columns: 1fr; }
  .modal-foot { flex-direction: column; align-items: stretch; text-align: center; }
  .modal-foot .primary-button { width: 100%; }
  .end-actions { flex-direction: column; }
  .site-footer { flex-wrap: wrap; font-size: 10px; }
}

@media (max-height: 700px) and (min-width: 621px) {
  .game-card { min-height: 310px; }
  .card-icon { margin-top: 14px; }
  .card-text { margin-top: 12px; }
  .keyboard-hint { display: none; }
  .home-main { padding-top: 22px; padding-bottom: 22px; }
}

@media (max-width: 380px) {
  .card-text { font-size: 1.22rem; }
  .card-icon { width: 44px; height: 44px; font-size: 22px; }
  .timer-ring-wrap { width: 54px; height: 54px; }
  .card-hint { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.001ms !important;
  }
}

content.text:
Now game.js. Complex. Let's carefully implement.

Imports:
```
import { CATEGORIES, CATEGORY_KEYS, DARES, daresFor, shuffle } from './dares.js';
```

Constants:
- COLOR palette for players: ["#f6ff5c","#67e8f9","#ff5ca8","#4ade80","#fb923c","#c084fc","#fb7185","#38bdf8"]
- LEVEL_LABEL = {1:"GENTLE",2:"BOLD",3:"FERAL"}
- STORAGE = keys.

DOM refs via `$` helper. Ensure IDs exist.

State:
```
const ui = { mode:'solo', length:10, turns:3, level:2, categories:new Set(CATEGORY_KEYS), players:[{name:'Player 1'},{name:'Player 2'}] };
let game = null;
let timerId=null;
let toastTimer=null;
let confettiRaf=0;
let lastTickSecond = null;
let audioCtx=null;
let muted = load...
```

Init:
- renderCategoryChips();
- renderPlayers();
- bind events.
- updateSetupSummary();
- updateSoundUi();
- set background maybe.
- show home (already active).
- expose maybe window.__dareDeck for tests/debug (handy for e2e). We can do `window.dareDeck = { getState: () => game, DARES,... }` but avoid production? Fine for debugging. Use `window.__dareDeck`.

Category chips:
```
categoryChips.innerHTML = CATEGORY_KEYS.map(key => `<button ... style="--cat:${c.color}" data-cat="${key}" aria-pressed="true"><span class=chip-icon>${c.icon}</span>${c.name}</button>`).join('');
```
Need HTML escape for names (none risky). fine.
Event delegation.

Filter deck preview:
```
const count = daresFor({categories:[...ui.categories], maxLevel:ui.level, playerCount: mode==='group'?ui.players.length:1}).length;
deckPreview.textContent = count;
```
If 0, maybe show 0 and start disabled? We'll disable start. But no categories? prevent last removal; level always 1+. Fine.

Start:
```
function startGame(configOverride) {
  const config = configOverride || readConfig();
  const players = config.players.map...
  const deck = shuffle(daresFor(...));
  if (!deck.length) ...
  const totalWanted = config.mode==='solo'? config.length : players.length*config.turns;
  const totalTurns = Math.min(totalWanted, deck.length);
  if (totalTurns < totalWanted) toast...
  game = { config, players, deck, deckSize:deck.length, totalTurns, turn:1, drawn:0, ... }
  // scores
  stopTimer(); clearResult; showScreen('game'); body.in-game; dealNext();
}
```
Deck size should be filtered total before drawing. `deckSize = deck.length`.
- players each {id, name, color, score:0, done:0, chicken:0, skip:0, streak:0, bestStreak:0, cats:{}}
- active index: computed at deal.

`readConfig`:
```
const players = ui.players.map(p=>p.name.trim()||...)
```
normalize unique:
```
function uniqueNames(names){ const seen={}; return names.map(n=>{let base=n; let count=seen[base]||0; seen[base]=count+1; return count?`${base} ${count+1}`:base;});}
```
Could cut to 14 chars. Fine.
- mode group requires >=2; if fewer show toast.
- selected categories; if none toast.
- length/turns.

showScreen:
```
document.querySelectorAll('.screen').forEach(el => { el.classList.toggle('is-active', el.id===`screen-${name}`); el.hidden = ...;});
window.scrollTo({top:0, behavior:'instant'});
```
Since `display:none` via class, hidden not needed. But `[hidden]` important for IDs. Set `hidden` for a11y.
- body class in-game toggled if name==='game'.
- On home, focus? no.

dealNext:
- if no game return.
- if turn > totalTurns or deck empty -> endGame.
- active index = mode group ? (turn-1)%players.length : 0.
- currentDare = deck.pop(); drawn++.
- If currentDare has min > players count? Deck built with playerCount, so okay.
- reset timer, phase = 'deal', result = null.
- renderGame();
- animate card.
- play draw.
- save nothing.

renderGame:
- activePlayer.
- progress label:
  - group: `Dare ${turn} of ${totalTurns}`
  - solo: same.
  - Maybe secondary.
- deck-left `${deck.length} left`
- score active player or total? In group, score pill should show active player's score. Update `score-value` to active.score. Label maybe not. We can use `aria-label="${name} score"`.
- progress fill = ((turn-1)/totalTurns)*100 maybe when card currently at turn 1, 0. Better `(turn-1)/totalTurns` so progress as completed. When result resolved maybe update to turn/total. We can set in updateProgress.
- players strip render if group.
- turn-kicker: group `${active.name.toUpperCase()}`? Actually turn-name should be active.name. turn-kicker "NOW PLAYING". For solo "YOUR TURN" and turn-name "Dare X". Let's set:
  - solo: kicker "YOUR TURN", name `Dare ${turn}`
  - group: kicker `${round}${ordinal} ROUND`? Simpler kicker "NOW PLAYING", name active.name.
  - avatar: emoji "🕺" for solo, initials for group.
- timer status "Ready".
- card category from CATEGORIES; set CSS `--cat`.
- badge text `${icon} ${name}`; level badge `${LEVEL_LABEL[level]} · LV ${lvl}`? Text "LEVEL 2 · BOLD". Good.
- card text.
- card index: `CARD ${String(drawn).padStart(3,'0')}` maybe `#${drawn} / ${deckSize}`.
- timer ring: total secs. `setTimerUi(total, total)` initial; if 0, add is-off, text "∞"; ring full? Set offset 0. Card hint:
  - if secs>0 "Take a breath. Start when ready."
  - else "No timer. Just vibes."
- result stamp hidden, classes removed.
- controls render.
- timer-status reset.

`setTimerUi(remaining,total)`:
```
const ratio = total>0 ? clamp(remaining/total,0,1) : 1;
ring.style.strokeDashoffset = `${169.65*(1-ratio)}`;
timerText.textContent = total>0 ? formatTime(remaining) : '∞';
wrap.classList.toggle('is-urgent', total>0 && remaining <= 5 && game.phase==='running');
```
Note setTimeout updates. `formatTime`: if >=60 `m:ss`, else `0:ss`? Use `Math.ceil(remaining)`. If remaining 0 => "0:00". For 20 => "0:20". For 45 => "0:45". Good.
- For timer total 0, add is-off.
- `aria-live` card already announces changes; timer won't be announced (good).

`renderControls()`:
- Clear.
- phase 'deal':
  - if timed: primary "Start timer" (id timer-btn), secondary "Done", ghost "Chicken out". Actually done before timer? Proof they did it without timer maybe. Keep. If timed and they press Done, points without bonus.
  - no timer: primary "Done", secondary "Chicken out".
  - skip button wide "Skip this dare (safe word)".
- 'running': primary "Pause", secondary "Done", ghost "Chicken out", skip maybe hidden? Keep skip.
- 'paused': primary "Resume", secondary "Done", ghost "Chicken out", skip.
- 'timeup': primary "Done", secondary "Chicken out", skip? no.
- 'result': next button full width "Next turn →" or "See results →". Maybe also "Replay card"? no.
- Need all buttons with event handlers assigned after innerHTML. Use data-action attributes and delegate click on controls container once. Simpler: set innerHTML and container onclick? Use event listener once on controls, inspect `data-action`.
- Buttons:
```
<button class="primary-button" data-action="timer">Start timer</button>
```
- `renderControls` uses innerHTML and class.
- For result next label: if next turn exists -> group ? `Next: ${nextPlayer.name}` : 'Next dare'; else 'See results'.
- Add a small skip ghost with data-action skip.

Handle control actions:
```
controls.addEventListener('click', e => {
 const btn=e.target.closest('[data-action]'); if(!btn) return;
 const action=btn.dataset.action;
 switch...
});
```
- timer: if phase deal -> start; running -> pause; paused -> resume.
- done -> resolve('done'); chicken -> resolve('chicken'); skip -> resolve('skip'); next -> nextTurn.

Timer functions:
```
function startTimer(){
 if(!game || !game.currentDare || game.currentDare.secs<=0) return;
 if(game.phase==='running') return;
 const secs = game.timer.remaining > 0 ? game.timer.remaining : game.timer.total;
 game.timer.remaining = secs;
 game.timer.endAt = performance.now()+secs*1000;
 game.timer.started = true;
 game.phase='running';
 lastTickSecond = null;
 clearInterval(timerId);
 timerId=setInterval(tick, 80);
 updateTimerStatus();
 renderControls();
 play('start');
}
```
For first start, `remaining` equals total. After pause, `remaining` preserved. For resume, if remaining <=0, reset to total? timeup no. Fine.
```
function tick(){
 const rem = Math.max(0,(endAt-performance.now())/1000);
 game.timer.remaining = rem;
 setTimerUi(rem,total);
 const sec=Math.ceil(rem);
 if (sec<=3 && sec>0 && sec!==lastTickSecond){ lastTickSecond=sec; play('tick'); }
 if(rem<=0){ stopTimer(); game.phase='timeup'; game.timer.remaining=0; setTimerUi(0,total); updateTimerStatus(); renderControls(); play('timeup'); }
}
```
- At 0, keep controls Done/Chicken. timer-status "Time!" and card hint "Timer's up. Did you hold it?" update card hint. Need update. 
- Pause:
```
game.timer.remaining = Math.max(0,(endAt-performance.now())/1000);
clearInterval; phase='paused'; update; renderControls; play('pause')
```
- stopTimer clears interval, not phase.
- On resolve, clear interval.

`updateTimerStatus`:
- based on phase: deal -> "Ready", running -> "Running", paused -> "Paused", timeup -> "Time!", result -> "Result".
- classes.

Resolve:
```
function resolve(kind){
 if (!game || game.phase==='result') return;
 stopTimer();
 const p=game.players[game.activeIndex];
 const dare=game.currentDare;
 const prevScore=p.score;
 let points=0;
