process.env.DISPLAY ||= ':' + (await import('node:fs')).readFileSync(join(process.env.HOME,'.local/share/omgithub-playwright/display'),'utf8').trim()
import { createRequire } from 'node:module'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse((await import('node:fs')).readFileSync(join(runtime, 'linux.json'),'utf8'))
const browser = await chromium.launch(config.browser.launchOptions)
for (let i=0;i<4;i++) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
  await page.goto('http://localhost:3002/?bust='+i, { waitUntil: 'load' })
  await page.waitForFunction(() => document.fonts.status === 'loaded')
  const t0 = Date.now()
  try { await page.locator('#start-game').click({ trial: true, timeout: 5000 }); console.log(i, 'trial ok', Date.now()-t0, await page.locator('#screen-home').getAttribute('class')) }
  catch(e) { console.log(i, 'fail', Date.now()-t0) }
  await page.close()
}
await browser.close()
EOF
