h1 span {
  color: var(--acid);
}

.hero-copy {
  max-width: 530px;
  margin: 24px 0 0;
  color: var(--muted);
  font-size: clamp(15px, 1.3vw, 17px);
  line-height: 1.65;
}

.hero-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 24px;
}
.badge {
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.035);
  color: #d9d2e6;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.015em;
}

.safety-note {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  max-width: 520px;
  margin: 26px 0 0;
  color: var(--muted-2);
  font-size: 12px;
  line-height: 1.55;
}

/* ── Deck fan ───────────────────────────────────────────────────────── */
.deck-fan {
  position: relative;
  width: min(400px, 92%);
  height: 210px;
  margin: 42px 0 0 4px;
}
.fan-card {
  position: absolute;
  left: 12px;
  bottom: 0;
  width: 250px;
  height: 158px;
  padding: 18px;
  border: 1px solid var(--line-strong);
  border-radius: 20px;
  background: linear-gradient(155deg, #241633, #150d21);
  box-shadow: 0 18px 36px rgba(0, 0, 0, 0.35);
  transform-origin: 50% 120%;
  transition: transform 0.35s var(--ease);
  font-weight: 900;
  letter-spacing: -0.04em;
  line-height: 1;
}
.setup h2 { font-size: 31px; }
.deck-pill {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: rgba(0, 0, 0, 0.18);
  line-height: 1.05;
}
.deck-pill strong { color: var(--acid); font-size: 20px; }
.deck-pill span { margin-top: 3px; color: var(--muted-2); font-size: 9px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; }

.segmented {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: rgba(0, 0, 0, 0.22);
}
.mode-switch { margin-bottom: 6px; }
.seg-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 42px;
  padding: 8px 10px;
  border: 0;
  border-radius: 11px;
  background: transparent;
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  transition: background 0.18s, color 0.18s, transform 0.18s;
}
.seg-btn:hover { color: var(--paper); background: rgba(255, 255, 255, 0.06); }
.seg-btn.is-active {
  background: var(--paper);
  color: #100b18;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
}
.seg-btn.is-active:hover { background: var(--paper); }

.option-block { margin-top: 18px; }
.label-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 9px;
}
.label-row.turns-label { margin-top: 16px; }
.label { color: var(--paper); font-size: 12px; font-weight: 800; letter-spacing: 0.04em; text-transform: uppercase; }
.label-hint { color: var(--muted-2); font-size: 11px; font-weight: 600; }
.mini-link {
  padding: 2px;
  border: 0;
  background: transparent;
  color: var(--acid);
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}
.mini-link:hover { text-decoration: underline; }
.pill-row { display: flex; flex-wrap: wrap; gap: 7px; }
.pill {

  transition: transform 0.35s var(--ease);
}
.fan-card span { font-size: 27px; }
.fan-card small {
  position: absolute;
  right: 16px;
  bottom: 14px;
  color: var(--muted-2);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.18em;
}
.fan-0 { transform: rotate(-12deg) translate(-13px, 8px); }
.fan-1 { transform: rotate(-5deg) translate(-3px, 2px); }
.fan-2 { transform: rotate(3deg) translate(12px, 0); }
.deck-fan:hover .fan-0 { transform: rotate(-16deg) translate(-22px, 7px); }
.deck-fan:hover .fan-1 { transform: rotate(-7deg) translate(-7px, 2px); }
.deck-fan:hover .fan-2 { transform: rotate(5deg) translate(18px, 0); }
.fan-front {
  width: 276px;
  height: 172px;
  bottom: 12px;
  left: 42px;
  padding: 16px 18px;
  background: linear-gradient(160deg, #fffde1, #f6ff5c 55%, #d9e700);
  color: #100b18;
  border-color: rgba(255, 255, 255, 0.5);
  transform: rotate(-2deg) translateY(-4px);
  box-shadow: 0 24px 54px rgba(0, 0, 0, 0.5), 0 0 50px rgba(246, 255, 92, 0.1);
  display: flex;
  flex-direction: column;
}
.fan-front-top, .fan-front-foot {
  display: flex;
  justify-content: space-between;
  color: rgba(16, 11, 24, 0.68);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.16em;
}
.fan-front strong {
  margin: auto 0;
  font-family: var(--font-display);
  font-size: 21px;
  font-weight: 900;
  line-height: 1.02;
  letter-spacing: -0.035em;
  text-transform: uppercase;
}

